import{_ as n,C as s,o as d,c as l,a5 as r,j as a,E as i}from"./chunks/framework.a5no_H3L.js";const y=JSON.parse('{"title":"Spring 核心原理概览","description":"你写的 @Service 里没有一个 new，依赖却都能用；你写的 @Transactional 方法里没有一行事务代码，抛出 RuntimeException 却能自动回滚。前者靠 IoC 容器替你管理对象与依赖，后者靠 AOP 替你包一层代理。Spring 的上层能力大多长在这两套机制上，本专题就从它们讲起。","frontmatter":{},"headers":[],"relativePath":"spring/01-core/chapter-01-spring-overview.md","filePath":"spring/01-core/chapter-01-spring-overview.md"}'),c={name:"spring/01-core/chapter-01-spring-overview.md"},o={"data-src-line":"24","data-src-file":"spring/01-core/chapter-01-spring-overview.md"},p={"data-src-line":"50","data-src-file":"spring/01-core/chapter-01-spring-overview.md"},g={"data-src-line":"63","data-src-file":"spring/01-core/chapter-01-spring-overview.md"};function v(f,e,h,m,x,w){const t=s("SvgDiagram");return d(),l("div",null,[e[0]||(e[0]=r('<h1 id="spring-核心原理概览" tabindex="-1" data-src-line="1" data-src-file="spring/01-core/chapter-01-spring-overview.md">Spring 核心原理概览 <a class="header-anchor" href="#spring-核心原理概览" aria-label="Permalink to &quot;Spring 核心原理概览&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="spring/01-core/chapter-01-spring-overview.md"><p data-src-line="3" data-src-file="spring/01-core/chapter-01-spring-overview.md">你写的 <code>@Service</code> 里没有一个 <code>new</code>，依赖却都能用；你写的 <code>@Transactional</code> 方法里没有一行事务代码，抛出 <code>RuntimeException</code> 却能自动回滚。前者靠 IoC 容器替你管理对象与依赖，后者靠 AOP 替你包一层代理。Spring 的上层能力大多长在这两套机制上，本专题就从它们讲起。</p></blockquote><h2 id="_1-为什么会有-spring" tabindex="-1" data-src-line="5" data-src-file="spring/01-core/chapter-01-spring-overview.md">1. 为什么会有 Spring <a class="header-anchor" href="#_1-为什么会有-spring" aria-label="Permalink to &quot;1. 为什么会有 Spring&quot;">​</a></h2><p data-src-line="7" data-src-file="spring/01-core/chapter-01-spring-overview.md">Spring 不是凭空设计出来的，它是对一个具体历史问题的回应。2002 年前后，Java 企业开发的主流方案是 J2EE 规范，EJB（Enterprise JavaBeans）是其中标准化的企业级组件模型。但 EJB 2.x 的代价很高：</p><table tabindex="0"><thead data-src-line="9" data-src-file="spring/01-core/chapter-01-spring-overview.md"><tr data-src-line="9" data-src-file="spring/01-core/chapter-01-spring-overview.md"><th style="text-align:left;">EJB 2.x 的负担</th><th style="text-align:left;">具体表现</th></tr></thead><tbody data-src-line="11" data-src-file="spring/01-core/chapter-01-spring-overview.md"><tr data-src-line="11" data-src-file="spring/01-core/chapter-01-spring-overview.md"><td style="text-align:left;">组件膨胀</td><td style="text-align:left;">典型 EJB 2.x 开发模式下，一个业务 Bean 要写 Home 接口、Local/Remote 接口、实现类和 <code>ejb-jar.xml</code>，一个类配多个文件</td></tr><tr data-src-line="12" data-src-file="spring/01-core/chapter-01-spring-overview.md"><td style="text-align:left;">强制容器</td><td style="text-align:left;">Bean 必须跑在 EJB 容器里，离开容器无法运行，写单元测试要先搭起容器环境</td></tr><tr data-src-line="13" data-src-file="spring/01-core/chapter-01-spring-overview.md"><td style="text-align:left;">持久化笨重</td><td style="text-align:left;">实体 Bean 用 CMP 做对象关系映射，表达能力弱，复杂查询很难写</td></tr><tr data-src-line="14" data-src-file="spring/01-core/chapter-01-spring-overview.md"><td style="text-align:left;">侵入性强</td><td style="text-align:left;">Bean 必须实现 EJB 规定的接口、抛规定的异常，业务代码和框架深度耦合</td></tr></tbody></table><p data-src-line="16" data-src-file="spring/01-core/chapter-01-spring-overview.md">Rod Johnson 在 2002 年出版的《Expert One-on-One J2EE Design and Development》里系统论证了一件事：<strong>没有 EJB，企业应用照样能写好</strong>。他给的替代品是一套朴素的组合，普通 POJO 加依赖注入来组装对象，AOP 来织入横切逻辑。</p><p data-src-line="18" data-src-file="spring/01-core/chapter-01-spring-overview.md">2003 年这套代码以 Spring 之名开源（Apache 2.0 许可），2004 年 3 月发布 1.0。它的核心目标，是把对象从 EJB 容器里解放出来，回到普通 POJO。组装交给 IoC，横切交给 AOP，本专题就围绕这两块地基展开。</p><h2 id="_2-版本演进" tabindex="-1" data-src-line="20" data-src-file="spring/01-core/chapter-01-spring-overview.md">2. 版本演进 <a class="header-anchor" href="#_2-版本演进" aria-label="Permalink to &quot;2. 版本演进&quot;">​</a></h2><p data-src-line="22" data-src-file="spring/01-core/chapter-01-spring-overview.md">从 2004 年的 1.0 到 2022 年的 6.0，Spring Framework 每次大版本升级都在回应一个具体的问题。下表也纳入了 Spring Boot，它是建立在 Framework 之上的另一条产品线：</p>',9)),a("p",o,[i(t,{src:"/spring/spring-core-timeline.svg",alt:"Spring 生态演进"})]),e[1]||(e[1]=r('<table tabindex="0"><thead data-src-line="26" data-src-file="spring/01-core/chapter-01-spring-overview.md"><tr data-src-line="26" data-src-file="spring/01-core/chapter-01-spring-overview.md"><th style="text-align:left;">版本</th><th style="text-align:left;">年份</th><th style="text-align:left;">主要变化</th></tr></thead><tbody data-src-line="28" data-src-file="spring/01-core/chapter-01-spring-overview.md"><tr data-src-line="28" data-src-file="spring/01-core/chapter-01-spring-overview.md"><td style="text-align:left;">1.0</td><td style="text-align:left;">2004</td><td style="text-align:left;">轻量容器落地，IoC 和 AOP 成型，核心容器、数据访问、Web 三层骨架搭起来</td></tr><tr data-src-line="29" data-src-file="spring/01-core/chapter-01-spring-overview.md"><td style="text-align:left;">2.0 / 2.5</td><td style="text-align:left;">2006 / 2007</td><td style="text-align:left;">XML 配置越堆越厚，2.5 引入 <code>@Autowired</code>、<code>@Component</code>，装配开始从 XML 挪进代码</td></tr><tr data-src-line="30" data-src-file="spring/01-core/chapter-01-spring-overview.md"><td style="text-align:left;">3.0</td><td style="text-align:left;">2009</td><td style="text-align:left;"><code>@Configuration</code> + <code>@Bean</code> 提供了一种不用 XML 的 Java Config 装配方式</td></tr><tr data-src-line="31" data-src-file="spring/01-core/chapter-01-spring-overview.md"><td style="text-align:left;">4.0</td><td style="text-align:left;">2013</td><td style="text-align:left;">全面支持 Java 8 特性，补上 <code>@RestController</code>、WebSocket 等 Web 能力</td></tr><tr data-src-line="32" data-src-file="spring/01-core/chapter-01-spring-overview.md"><td style="text-align:left;">Spring Boot 1.0</td><td style="text-align:left;">2014</td><td style="text-align:left;">Spring 自身的配置又成了负担，Boot 用自动配置加约定优于配置，大幅削减启动配置</td></tr><tr data-src-line="33" data-src-file="spring/01-core/chapter-01-spring-overview.md"><td style="text-align:left;">5.0</td><td style="text-align:left;">2017</td><td style="text-align:left;">引入基于 Reactive Streams 的 WebFlux，为 I/O 密集场景提供非阻塞的响应式栈</td></tr><tr data-src-line="34" data-src-file="spring/01-core/chapter-01-spring-overview.md"><td style="text-align:left;">6.0</td><td style="text-align:left;">2022</td><td style="text-align:left;">基线升到 JDK 17，命名空间从 <code>javax</code> 切到 <code>jakarta</code>（Jakarta EE 9+），并推进 AOT 与原生镜像支持</td></tr></tbody></table><p data-src-line="36" data-src-file="spring/01-core/chapter-01-spring-overview.md">装配方式从 XML 走向注解、Java Config，再到 Boot 的自动配置；运行模型从传统容器式应用，走向 WebFlux 的响应式处理和 AOT、原生镜像。这些机制彼此并不替代，注解与 XML、WebFlux 与 Spring MVC 至今并存，各自解决的是不同阶段最突出的痛点。</p><h2 id="_3-框架版图" tabindex="-1" data-src-line="38" data-src-file="spring/01-core/chapter-01-spring-overview.md">3. 框架版图 <a class="header-anchor" href="#_3-框架版图" aria-label="Permalink to &quot;3. 框架版图&quot;">​</a></h2><p data-src-line="40" data-src-file="spring/01-core/chapter-01-spring-overview.md">Spring Framework 由多个模块组成，核心容器只是其中一条主线。理解这条主线，可以沿着三层自下而上地读，分层的收益是只想用轻量容器的人不必背上全部依赖：</p><table tabindex="0"><thead data-src-line="42" data-src-file="spring/01-core/chapter-01-spring-overview.md"><tr data-src-line="42" data-src-file="spring/01-core/chapter-01-spring-overview.md"><th style="text-align:left;">模块</th><th style="text-align:left;">层职责</th><th style="text-align:left;">关键类型</th></tr></thead><tbody data-src-line="44" data-src-file="spring/01-core/chapter-01-spring-overview.md"><tr data-src-line="44" data-src-file="spring/01-core/chapter-01-spring-overview.md"><td style="text-align:left;"><code>spring-core</code></td><td style="text-align:left;">底层基础设施与通用工具（资源访问、类型转换、排序），不含 Bean 定义</td><td style="text-align:left;"><code>Resource</code>、<code>Ordered</code></td></tr><tr data-src-line="45" data-src-file="spring/01-core/chapter-01-spring-overview.md"><td style="text-align:left;"><code>spring-beans</code></td><td style="text-align:left;">定义 Bean 的元数据与创建工厂，IoC 容器的底座</td><td style="text-align:left;"><code>BeanDefinition</code>、<code>BeanFactory</code></td></tr><tr data-src-line="46" data-src-file="spring/01-core/chapter-01-spring-overview.md"><td style="text-align:left;"><code>spring-context</code></td><td style="text-align:left;">在 beans 之上叠加事件、国际化、注解配置等应用上下文能力</td><td style="text-align:left;"><code>ApplicationContext</code>、<code>MessageSource</code></td></tr></tbody></table><p data-src-line="48" data-src-file="spring/01-core/chapter-01-spring-overview.md">图中箭头即依赖方向，只允许上层依赖下层。由此能推出一个常被问到的结论：<code>BeanFactory</code> 定义在 <code>spring-beans</code>，<code>ApplicationContext</code> 定义在 <code>spring-context</code>，后者在前者之上叠加了应用上下文能力，详见 <a href="./chapter-02-ioc-container.html">IoC 容器</a>。AOP、事务、Web 这些能力，都建立在同一套 Bean 装配之上：</p>',6)),a("p",p,[i(t,{src:"/spring/spring-core-modules.svg",alt:"Spring 核心模块依赖关系"})]),e[2]||(e[2]=r('<h2 id="_4-知识地图" tabindex="-1" data-src-line="52" data-src-file="spring/01-core/chapter-01-spring-overview.md">4. 知识地图 <a class="header-anchor" href="#_4-知识地图" aria-label="Permalink to &quot;4. 知识地图&quot;">​</a></h2><p data-src-line="54" data-src-file="spring/01-core/chapter-01-spring-overview.md">本专题的六个模块连成一条主线。容器先学会创建 Bean（IoC），再看单个 Bean 从创建到销毁的完整流程（生命周期），依赖在这个流程里注入（DI），相互依赖时用三级缓存解开（循环依赖），横切逻辑靠代理增强（AOP），最后按条件决定哪些 Bean 生效（条件装配）。</p><ul data-src-line="56" data-src-file="spring/01-core/chapter-01-spring-overview.md"><li data-src-line="56" data-src-file="spring/01-core/chapter-01-spring-overview.md"><strong>IoC 容器</strong>：入口，先解决「谁创建对象」。容器能创建 Bean，后面的注入、代理才有对象可操作。</li><li data-src-line="57" data-src-file="spring/01-core/chapter-01-spring-overview.md"><strong>Bean 生命周期</strong>：单个 Bean 从 <code>new</code> 到销毁的完整流程，是注入、循环依赖、代理共同依赖的骨架。</li><li data-src-line="58" data-src-file="spring/01-core/chapter-01-spring-overview.md"><strong>依赖注入</strong>：解决「依赖怎么进去」。构造器注入发生在实例化阶段，Setter 和字段注入发生在属性填充阶段，它不是生命周期里的单独一步。</li><li data-src-line="59" data-src-file="spring/01-core/chapter-01-spring-overview.md"><strong>AOP</strong>：解决「横切逻辑怎么复用」，代理对象通常在生命周期「初始化」阶段生成。</li><li data-src-line="60" data-src-file="spring/01-core/chapter-01-spring-overview.md"><strong>循环依赖</strong>：注入的极端情况，A 依赖 B、B 又依赖 A。Spring 用三级缓存提前暴露早期引用，解开部分单例循环依赖，三级缓存同时和 AOP 的早期代理有关。</li><li data-src-line="61" data-src-file="spring/01-core/chapter-01-spring-overview.md"><strong>条件装配</strong>：解决「哪些 Bean 该生效」，按条件决定 Bean 是否注册，是 Spring Boot 自动配置的基础。</li></ul>',3)),a("p",g,[i(t,{src:"/spring/spring-core-mindmap.svg",alt:"Spring 核心知识地图"})])])}const S=n(c,[["render",v]]);export{y as __pageData,S as default};
